                if (!q || !on(q)) continue;
                if (OPERATORS[q.matchName]) flag(out, KIND[q.matchName], q.name + ' ' + OPERATORS[q.matchName]);
                else if (STROKES[q.matchName]) strokeNeeds(q, out);
