                var drawnOf = [], keysMF = [], res;
                for (p = 0; p < g.length; p++) drawnOf.push(keyIndices(g[p]).drawn);
                var K = drawnOf[0].length;
                for (k = 0; k < K; k++) {
                    var rowK = [];
                    for (p = 0; p < g.length; p++) rowK.push(toMF(g[p].keyValue(drawnOf[p][k])));
                    keysMF.push(rowK);
                }
